<script setup>
import {ref,computed} from 'vue';import {Head,Link,useForm} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import ConfirmAction from '../Components/ConfirmAction.vue';import FormErrors from '../Components/FormErrors.vue';import {useExamContext} from '../exam-context';
const props=defineProps({exams:Object,questions:Array,subjects:Array});const {context,base,page}=useExamContext();const open=ref(false),editing=ref(null),selectedId=ref(null),action=ref(null);const selected=computed(()=>props.exams.data.find(exam=>exam.id===selectedId.value));const form=useForm({title:'',description:'',duration_minutes:120,subject_id:''});const attach=useForm({question_id:''});const owner=exam=>page.props.auth.user.role==='admin'||exam.created_by===page.props.auth.user.id;
function show(exam=null){editing.value=exam;form.clearErrors();Object.assign(form,exam?{title:exam.title,description:exam.description||'',duration_minutes:exam.duration_minutes,subject_id:exam.subject_id||''}:{title:'',description:'',duration_minutes:120,subject_id:''});open.value=true;}
function save(){form.submit(editing.value?'put':'post',base.value+'/exams'+(editing.value?'/'+editing.value.id:''),{onSuccess:()=>open.value=false});}
function status(exam){action.value={method:'put',url:base.value+`/exams/${exam.id}/status`,data:{status:exam.status==='published'?'draft':'published'},title:exam.status==='published'?'Đóng đề thi':'Mở đề thi',message:exam.status==='published'?'Đóng đề sẽ tạm chặn thí sinh bắt đầu hoặc tiếp tục bài đang làm.':'Mở đề để quản trị viên cấp quyền thi cho thí sinh?',button:exam.status==='published'?'Đóng đề':'Mở đề'};}
</script>
<template><Head :title="'Đề thi · '+context.name"/><AppLayout><div class="page-heading"><div><h1>Đề thi {{context.name}}</h1><p>Tạo đề, chọn học liệu riêng của phân hệ và mở thi.</p></div><button @click="show()">+ Thêm đề thi</button></div><div class="card"><div class="tablewrap"><table><thead><tr><th>Mã</th><th>Tên đề</th><th>Số câu / phút</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="exam in exams.data" :key="exam.id"><td>#{{exam.id}}</td><td class="table-title">{{exam.title}}<small v-if="exam.subject_id" class="cell-meta">{{subjects.find(subject=>subject.id===exam.subject_id)?.name}}</small></td><td>{{exam.questions_count}} câu · {{exam.duration_minutes}} phút</td><td><span class="pill">{{exam.status==='published'?'Đã mở thi':'Bản nháp'}}</span></td><td><div v-if="owner(exam)" class="actions"><button class="secondary" @click="selectedId=exam.id;attach.clearErrors()">Câu hỏi</button><button class="secondary" @click="show(exam)">Sửa</button><button class="secondary" @click="status(exam)">{{exam.status==='published'?'Đóng đề':'Mở đề'}}</button><button class="secondary" @click="action={url:base+'/exams/'+exam.id,title:'Xóa đề thi',message:'Xóa đề '+exam.title+'? Đề đã mở hoặc đã cấp quyền sẽ được giữ lại.'}">Xóa</button></div></td></tr><tr v-if="!exams.data.length"><td colspan="5" class="empty-state">Chưa có đề thi trong phân hệ này.</td></tr></tbody></table></div><div class="pagination"><Link v-if="exams.prev_page_url" :href="exams.prev_page_url">← Trước</Link><span>Trang {{exams.current_page}} / {{exams.last_page}}</span><Link v-if="exams.next_page_url" :href="exams.next_page_url">Tiếp →</Link></div></div>
<AppModal :open="open" :title="editing?'Sửa đề thi':'Thêm đề thi'" :busy="form.processing" @close="open=false"><form @submit.prevent="save"><FormErrors :errors="form.errors"/><div class="field"><label for="exam-title">Tên đề</label><input id="exam-title" v-model="form.title" required maxlength="255"/></div><div v-if="context.slug==='course'" class="field"><label for="exam-subject">Môn học</label><select id="exam-subject" v-model="form.subject_id" required><option value="" disabled>Chọn môn</option><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{subject.name}}</option></select></div><div class="field"><label for="exam-duration">Thời lượng (phút)</label><input id="exam-duration" v-model.number="form.duration_minutes" type="number" min="5" max="360" required/></div><div class="field"><label for="exam-description">Mô tả</label><textarea id="exam-description" v-model="form.description" rows="3"/></div><div class="modal-actions"><button type="button" class="secondary" @click="open=false">Hủy</button><button :disabled="form.processing">Lưu đề thi</button></div></form></AppModal>
<AppModal :open="!!selected" :title="'Câu hỏi trong đề · '+(selected?.title||'')" wide :busy="attach.processing" @close="selectedId=null"><template v-if="selected"><FormErrors :errors="attach.errors"/><p v-if="selected.status!=='draft'" class="notice">Đóng đề trước khi thay đổi câu hỏi. Bài thi đã bắt đầu giữ nguyên nội dung tại lúc bắt đầu.</p><form v-else class="filter-row" @submit.prevent="attach.post(base+'/exams/'+selected.id+'/questions',{preserveScroll:true,onSuccess:()=>attach.reset()})"><select v-model="attach.question_id" aria-label="Chọn câu hỏi thêm vào đề" required><option value="" disabled>Chọn câu hỏi cùng phân hệ{{context.slug==='course'?' và môn học':''}}</option><option v-for="question in questions.filter(question=>question.subject_id===selected.subject_id&&!selected.questions.some(item=>item.id===question.id))" :key="question.id" :value="question.id">#{{question.id}} · {{question.content.slice(0,100)}}</option></select><button :disabled="attach.processing">Thêm vào đề</button></form><div class="modal-list"><div v-for="(question,index) in selected.questions" :key="question.id"><p><strong>{{index+1}}.</strong> {{question.content}}</p><button v-if="selected.status==='draft'" class="secondary" @click="action={url:base+'/exams/'+selected.id+'/questions/'+question.id,title:'Gỡ câu hỏi',message:'Gỡ câu hỏi này khỏi đề? Câu hỏi vẫn được giữ trong ngân hàng.'}">Gỡ</button></div><p v-if="!selected.questions.length" class="muted">Đề chưa có câu hỏi.</p></div></template></AppModal><ConfirmAction :action="action" @close="action=null"/></AppLayout></template>
